#[path = "src/earcut.rs"]
mod earcut;

use std::io::Write;

/// Emulates C `atoi`: skip leading whitespace (C locale), optional sign,
/// then digits until the first non-digit. Empty/garbage -> 0.
fn atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = (val * 10 + i64::from(b[i] - b'0')).min(i64::from(i32::MAX) + 1);
        i += 1;
    }
    let val = if neg { -val } else { val };
    val.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
}

fn main() {
    let mut n: i32 = 4;
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let mut i: i32 = 0;
    while i < n {
        let offset = f64::from(i * 2);
        let nf = f64::from(n);
        polygon.push(vec![
            [offset, offset],
            [offset + nf, offset],
            [offset + nf, offset + nf],
            [offset, offset + nf],
        ]);
        i += 1;
    }

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for idx in indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

