//! Faithful port of mapbox's earcut.hpp (ear-clipping triangulation with
//! z-order hashing), using a `Vec<Node>` arena with `usize` links instead of
//! pointers. `NULL` plays the role of `nullptr`.

pub const NULL: usize = usize::MAX;

struct Node {
    i: u32, // index of the vertex in the flattened input
    x: f64,
    y: f64,
    prev: usize, // circular doubly-linked list of the polygon ring
    next: usize,
    z: i32, // z-order curve value
    prev_z: usize, // z-order linked list
    next_z: usize,
    steiner: bool,
}

pub struct Earcut {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    vertices: u32, // running global vertex index across all rings
    hashing: bool,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

/// Triangulate a polygon given as a list of rings (first = outer, rest = holes).
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut ec = Earcut {
        nodes: Vec::new(),
        indices: Vec::new(),
        vertices: 0,
        hashing: false,
        min_x: 0.0,
        min_y: 0.0,
        inv_size: 0.0,
    };
    ec.run(polygon);
    ec.indices
}

impl Earcut {
    fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        if points.is_empty() {
            return;
        }

        let mut threshold: i64 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i64;
            len += points[i].len();
            i += 1;
        }

        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NULL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            let mut min_x = self.nodes[outer_node].x;
            let mut min_y = self.nodes[outer_node].y;
            let mut max_x = self.nodes[outer_node].x;
            let mut max_y = self.nodes[outer_node].y;
            loop {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                if x < min_x {
                    min_x = x;
                }
                if y < min_y {
                    min_y = y;
                }
                if x > max_x {
                    max_x = x;
                }
                if y > max_y {
                    max_y = y;
                }
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }
            self.min_x = min_x;
            self.min_y = min_y;
            let mut inv_size = (max_x - min_x).max(max_y - min_y);
            inv_size = if inv_size != 0.0 { 1.0 / inv_size } else { 0.0 };
            self.inv_size = inv_size;
        }

        self.earcut_linked(outer_node, 0);
    }

    fn create_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        let idx = self.nodes.len();
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NULL,
            next: NULL,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        });
        idx
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: usize) -> usize {
        let p = self.create_node(i, x, y);
        if last == NULL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let ln = self.nodes[last].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = last;
            self.nodes[ln].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let pz = self.nodes[p].prev_z;
        let nz = self.nodes[p].next_z;
        if pz != NULL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NULL {
            self.nodes[nz].prev_z = pz;
        }
    }

    // create a circular doubly linked list from a ring in the specified winding order
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut sum = 0.0f64;
        if len > 0 {
            let mut j = len - 1;
            for i in 0..len {
                sum += (points[j][0] - points[i][0]) * (points[i][1] + points[j][1]);
                j = i;
            }
        }

        let mut last = NULL;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i as u32, points[i][0], points[i][1], last);
            }
        } else {
            let mut i = len;
            while i > 0 {
                i -= 1;
                last = self.insert_node(self.vertices + i as u32, points[i][0], points[i][1], last);
            }
        }

        if last != NULL && self.equals(last, self.nodes[last].next) {
            self.remove_node(last);
            last = self.nodes[last].next;
        }

        self.vertices += len as u32;
        last
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, mut end: usize) -> usize {
        if start == NULL {
            return start;
        }

        let mut p = start;
        loop {
            let mut again = false;

            let next = self.nodes[p].next;
            let prev = self.nodes[p].prev;
            if !self.nodes[p].steiner
                && (self.equals(p, next) || self.area(prev, p, next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, mut ear: usize, pass: i32) {
        if ear == NULL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let ear_found = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if ear_found {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                if pass == 0 {
                    let f = self.filter_points(ear, ear);
                    self.earcut_linked(f, 1);
                } else if pass == 1 {
                    let f = self.filter_points(ear, ear);
                    ear = self.cure_local_intersections(f);
                    self.earcut_linked(ear, 2);
                } else if pass == 2 {
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[ear].next;
        p = self.nodes[p].next;

        while p != self.nodes[ear].prev {
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if self.point_in_triangle_nodes(a, b, c, p) && self.area(pp, p, pn) >= 0.0 {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = self.nodes[a]
            .x
            .min(self.nodes[b].x.min(self.nodes[c].x));
        let min_ty = self.nodes[a]
            .y
            .min(self.nodes[b].y.min(self.nodes[c].y));
        let max_tx = self.nodes[a]
            .x
            .max(self.nodes[b].x.max(self.nodes[c].x));
        let max_ty = self.nodes[a]
            .y
            .max(self.nodes[b].y.max(self.nodes[c].y));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let mut p = self.nodes[ear].next_z;

        while p != NULL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle_nodes(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // look for points in both directions along the curve
        p = self.nodes[ear].prev_z;

        while p != NULL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle_nodes(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let p_next = self.nodes[p].next;
            let b = self.nodes[p_next].next;

            if !self.equals(a, b)
                && self.intersects(a, p, p_next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, p)
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a2 = self.filter_points(a, self.nodes[a].next);
                    c = self.filter_points(c, self.nodes[c].next);

                    // run earcut on each half
                    self.earcut_linked(a2, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link every hole into the outer loop, producing a single-ring polygon without holes
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], mut outer_node: usize) -> usize {
        let mut queue: Vec<usize> = Vec::new();
        for i in 1..points.len() {
            let list = self.linked_list(&points[i], false);
            if list != NULL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|&a, &b| {
            let (na, nb) = (&self.nodes[a], &self.nodes[b]);
            na.x.partial_cmp(&nb.x).unwrap().then(na.y.partial_cmp(&nb.y).unwrap())
        });

        // process holes from left to right
        for &hole in &queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    // find a bridge between vertices that connects hole with an outer ring and link it
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NULL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, brn);
        let on = self.nodes[outer_node].next;
        self.filter_points(outer_node, on)
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NULL;

        // find a segment intersected by a ray from the hole's leftmost point to the left;
        // segment's endpoint with lesser x will be potential connection point
        loop {
            let (py, pny) = (self.nodes[p].y, self.nodes[self.nodes[p].next].y);
            if hy <= py && hy >= pny && pny != py {
                let px = self.nodes[p].x;
                let pnx = self.nodes[self.nodes[p].next].x;
                let x = px + (hy - py) * (pnx - px) / (pny - py);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == py {
                            return p;
                        }
                        if hy == pny {
                            return self.nodes[p].next;
                        }
                    }
                    m = if px < pnx { p } else { self.nodes[p].next };
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        if m == NULL {
            return NULL;
        }

        if hx == qx {
            return m; // hole touches outer segment; pick leftmost endpoint
        }

        // look for points inside the triangle of hole point, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the point of the minimum angle with the ray as connection point
        let stop = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;
        let mut tan_min = f64::INFINITY;

        p = m;

        loop {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            if hx >= px
                && px >= mx
                && hx != px
                && self.point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x
                                || (px == self.nodes[m].x && self.sector_contains_sector(m, p)))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;
            self.nodes[p].prev_z = prev;
            self.nodes[p].next_z = next;
            p = next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm on z-order (nextZ links)
    fn sort_linked(&mut self, start: usize) {
        let mut list = start;
        let mut in_size: usize = 1;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0usize;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return;
            }

            in_size *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x: f64, y: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = (32767.0 * (x - self.min_x) * self.inv_size) as i32;
        let mut y = (32767.0 * (y - self.min_y) * self.inv_size) as i32;

        x = (x | x.wrapping_shl(8)) & 0x00FF00FF;
        x = (x | x.wrapping_shl(4)) & 0x0F0F0F0F;
        x = (x | x.wrapping_shl(2)) & 0x33333333;
        x = (x | x.wrapping_shl(1)) & 0x55555555;

        y = (y | y.wrapping_shl(8)) & 0x00FF00FF;
        y = (y | y.wrapping_shl(4)) & 0x0F0F0F0F;
        y = (y | y.wrapping_shl(2)) & 0x33333333;
        y = (y | y.wrapping_shl(1)) & 0x55555555;

        x | y.wrapping_shl(1)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (lx, ly) = (self.nodes[leftmost].x, self.nodes[leftmost].y);
            if px < lx || (px == lx && py < ly) {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    // check if a point lies within a convex triangle (node coordinates)
    fn point_in_triangle_nodes(&self, a: usize, b: usize, c: usize, p: usize) -> bool {
        self.point_in_triangle(
            self.nodes[a].x,
            self.nodes[a].y,
            self.nodes[b].x,
            self.nodes[b].y,
            self.nodes[c].x,
            self.nodes[c].y,
            self.nodes[p].x,
            self.nodes[p].y,
        )
    }

    // check if a point lies within a convex triangle
    #[allow(clippy::too_many_arguments)]
    fn point_in_triangle(
        &self,
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) >= (ax - px) * (cy - py)
            && (ax - px) * (by - py) >= (bx - px) * (ay - py)
            && (bx - px) * (cy - py) >= (cx - px) * (by - py)
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let (an, ap, bn, bp) = (
            self.nodes[a].next,
            self.nodes[a].prev,
            self.nodes[b].next,
            self.nodes[b].prev,
        );
        self.nodes[an].i != self.nodes[b].i
            && self.nodes[ap].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    // check if two points are equal
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let (ap, an) = (self.nodes[a].prev, self.nodes[a].next);
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        let mut inside = false;
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            let (px_p, py_p) = (self.nodes[p].x, self.nodes[p].y);
            let (px_n, py_n) = (self.nodes[pn].x, self.nodes[pn].y);
            if (py_p > py) != (py_n > py)
                && py_n != py_p
                && px < (px_n - px_p) * (py - py_p) / (py_n - py_p) + px_p
            {
                inside = !inside;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        inside
    }

    // link two polygon vertices with a bridge;
    // if the vertices belong to the same ring, it splits polygon into two;
    // if one belongs to the outer ring and another to a hole, it merges it into a single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.create_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.create_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;
        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;
        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;
        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // check if a sector between two polygon nodes contains another sector
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }
