fn isEarVariant(&self, ear: usize) -> bool {
    // variant switches for reverse-engineering the reference binary
    let walk_from_next = std::env::var("EAR_FROM_NEXT").is_ok();
    let stop_at_ear = std::env::var("EAR_STOP_AT_EAR").is_ok();
    let no_reflex = std::env::var("EAR_NO_REFLEX").is_ok();
    let strict_reflex = std::env::var("EAR_STRICT_REFLEX").is_ok();

    let a = self.nodes[ear].prev;
    let b = ear;
    let c = self.nodes[ear].next;

    if self.area(a, b, c) >= 0.0 {
        return false; // reflex, can't be an ear
    }

    let stop = if stop_at_ear { ear } else { self.nodes[ear].prev };
    let mut p = if walk_from_next {
        self.nodes[ear].next
    } else {
        self.nodes[self.nodes[ear].next].next
    };

    while p != stop {
        let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
        let reflex_ok = if no_reflex {
            true
        } else if strict_reflex {
            self.area(pp, p, pn) > 0.0
        } else {
            self.area(pp, p, pn) >= 0.0
        };
        if self.point_in_triangle_nodes(a, b, c, p) && reflex_ok {
            return false;
        }
        p = self.nodes[p].next;
    }

    true
}

